a.role_id,
a.role_name,
a.create_time,
a.creator_id,
a.sys_state
from sys_role a
where 1 = 1
 and a.role_id = #{roleId, jdbcType=BIGINT}
 and a.role_name = #{roleName, jdbcType=VARCHAR}
 and a.create_time = #{createTime, jdbcType=TIMESTAMP}
 and a.creator_id = #{creatorId, jdbcType=BIGINT}
 and a.sys_state = #{sysState, jdbcType=INTEGER}

